import{_ as e,o,c as t,a2 as r}from"./chunks/framework.1C62pOns.js";const u=JSON.parse('{"title":"Manual das telas","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/index.md","filePath":"pt/interface/index.md","lastUpdated":1787856241000}'),s={name:"pt/interface/index.md"};function n(i,a,l,d,p,m){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="manual-das-telas" tabindex="-1">Manual das telas <a class="header-anchor" href="#manual-das-telas" aria-label="Permalink to &quot;Manual das telas&quot;">​</a></h1><p>Este manual não lista campo por campo. Ele explica <strong>para que serve cada tela, que decisões ela pede de você e onde as pessoas costumam tropeçar</strong> — que é o que não dá para adivinhar olhando a interface.</p><p>Os rótulos dos campos você lê na própria tela, e eles mudam de versão para versão; o motivo de cada escolha, não.</p><h2 id="roteiro" tabindex="-1">Roteiro <a class="header-anchor" href="#roteiro" aria-label="Permalink to &quot;Roteiro&quot;">​</a></h2><p>Se está começando, siga nesta ordem — cada peça depende da anterior:</p><ol><li><strong><a href="/pro-agent-hub-installer/pt/interface/primeiros-passos">Primeiros passos</a></strong> — entrar, se localizar no menu, entender o painel.</li><li><strong><a href="/pro-agent-hub-installer/pt/interface/provedores-modelos">Provedores e modelos</a></strong> — de onde vem a inteligência. Sem isto, nada mais funciona.</li><li><strong><a href="/pro-agent-hub-installer/pt/interface/conhecimento">Conhecimento e fontes de dados</a></strong> — o que a plataforma sabe além do modelo.</li><li><strong><a href="/pro-agent-hub-installer/pt/interface/agentes">Agentes, times e chat</a></strong> — quem conversa e executa.</li><li><strong><a href="/pro-agent-hub-installer/pt/interface/workflows">Workflows</a></strong> — automação, visual ou em código.</li><li><strong><a href="/pro-agent-hub-installer/pt/interface/planejadores">Planejadores</a></strong> — agentes que trabalham em ciclo até resolver um objetivo.</li><li><strong><a href="/pro-agent-hub-installer/pt/interface/mcp">Serviços MCP</a></strong> — ferramentas externas e as suas próprias.</li><li><strong><a href="/pro-agent-hub-installer/pt/interface/apps">Apps</a></strong> — telas web construídas na plataforma.</li><li><strong><a href="/pro-agent-hub-installer/pt/interface/integracoes">Integrações</a></strong> — WhatsApp e Microsoft Teams.</li><li><strong><a href="/pro-agent-hub-installer/pt/interface/administracao">Administração</a></strong> — grupos, usuários, configurações, consumo e a cópia de dados entre ambientes.</li></ol><h2 id="o-que-e-comum-a-todas-as-telas" tabindex="-1">O que é comum a todas as telas <a class="header-anchor" href="#o-que-e-comum-a-todas-as-telas" aria-label="Permalink to &quot;O que é comum a todas as telas&quot;">​</a></h2><p><strong>Lista e detalhe.</strong> Quase todo cadastro tem uma tela de lista, com busca, e uma de detalhe, com abas. A lista tem um filtro <em>&quot;apenas ativos&quot;</em> — registros desabilitados continuam existindo, só saem da frente.</p><p><strong>Desabilitar não é excluir.</strong> Um registro desabilitado para de ser usado mas mantém o histórico e os vínculos. Excluir é definitivo e costuma ser recusado quando há algo apontando para ele.</p><p><strong>Salvar é explícito.</strong> Sair de uma tela com alterações não salvas dispara um aviso. Nada é gravado enquanto você não confirma.</p><p><strong>O que você enxerga depende do seu grupo.</strong> Um usuário não-master só vê os agentes, times, workflows, planejadores, serviços MCP e Apps que algum grupo dele liberou — e com o modo que o grupo concedeu: <em>leitura</em> permite abrir e executar, <em>escrita</em> permite salvar. Ver <a href="/pro-agent-hub-installer/pt/interface/administracao">Administração</a>.</p>',11)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
